KURN_FN uint32_t kfsr(uint32_t lo, uint32_t hi, int sh) {  // (hi:lo) >> sh, low 32 bits (sh 0..31)
#ifdef KURN_EMU
  return (uint32_t)((((uint64_t)hi << 32) | lo) >> sh);
#else
  return __funnelshift_r(lo, hi, sh);
#endif
}
#define FVB 64

// epi=fv region (kg_fv_setup), after the prepared weights at KG_FV_OFF(N, K), 256-byte aligned:
//   u32 hdr[16]                 magic 'KFV1', FVB, column key, lambda (f32 bits), checks, fails, worst passing
//                               |C - X| / tau (f32 bits), N, K
//   i32 cnt[NB]                 CTAs done per block (the last one compares and resets)
//   f64 acc[NB][FV_MC][2][2]    per block, column slot, probe: (sum_n r[n] Y[m][n], sum_k F[k] x[m][k])
//   f64 s2[NB][FV_MC]           sum_k x[m][k]^2 G2[k]: the tolerance's magnitude (from trusted inputs only)
//   f32 F[NB][K][2]             fingerprint W_b^T r_p of each block of FVB rows, both probes interleaved
//   u16 G2[NB][K]               sum_n W[n][k]^2 over the block, bf16 rounded up
//   u32 signs[2][(N + 31) / 32] the secret row probes r_p (bit = 1: -1)
#define FV_MC 16
#define FV_NB(N) (((N) + FVB - 1) / FVB)
#define FV_ACC(N) ((64 + 4 * (size_t)FV_NB(N) + 15) / 16 * 16)
#define FV_S2(N) (FV_ACC(N) + (size_t)FV_NB(N) * FV_MC * 32)
#define FV_F(N) (FV_S2(N) + (size_t)FV_NB(N) * FV_MC * 8)
#define FV_G2(N, K) (FV_F(N) + (size_t)FV_NB(N) * (K) * 8)
#define FV_SG(N, K) ((FV_G2(N, K) + (size_t)FV_NB(N) * (K) * 2 + 15) / 16 * 16)
#define FV_BYTES(N, K) (FV_SG(N, K) + 8 * (size_t)(((N) + 31) / 32))
// secret column signs (bit p: probe p) that fold columns m and m + FV_MC, ... into one slot
KURN_FN uint32_t kfv_csign(uint32_t key, int m) {
  uint32_t x = key ^ ((uint32_t)m * 0x9E3779B9u);
  x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16;
  return x;
}

// A frag plane: [N/16][K/KT][32 lanes][16 B]; then scale plane [N/16][K/256][8][u32: row g | row g+8]
static __global__ void __launch_bounds__(NT, 1)
kg_gemm(const uint8_t *__restrict__ W, const void *__restrict__ Xin, float *__restrict__ Y, int N, int K, int M, int ksplit, uint8_t *__restrict__ FV) {
#ifdef KURN_EMU
  static uint8_t kg_smem_emu[SMEM_BYTES + 16] __attribute__((aligned(16)));
  uint8_t *smem = kg_smem_emu;
#else
  extern __shared__ __align__(16) uint8_t kg_smem[];
  uint8_t *smem = kg_smem;
#endif
  uint8_t *As = smem;
  uint8_t *Bs0 = smem + STAGES * A_STAGE;
  float *XS0 = (float *)(Bs0 + STAGES * B_STAGE);
  (void)XS0;
  const int nkt = K / KT;
  const uint8_t *Wa = W;
  const uint8_t *Ws = W + (size_t)(N / 16) * nkt * 512;
  const uint8_t *Wm = Ws;
  (void)Ws; (void)Wm;
  const uint2 *tbmlut = (const uint2 *)(smem + SMEM_BYTES - 2048);
  for (int i = threadIdx.x; i < 512; i += NT) ((uint32_t *)(smem + SMEM_BYTES - 2048))[i] = kTBM[i];
  const uint8_t *Wt = Ws + (size_t)(N / 16) * (K / 256) * 32;                            // u32 sign-stream base per tile
  const uint32_t *Wg = (const uint32_t *)(Wt + ((size_t)(N / 16) * (K / 256) + 1) * 4);  // sign words
  const int tid = threadIdx.x, lane = tid & 31, warp = tid >> 5, g = lane >> 2, t = lane & 3;
  const int wr = warp % 4, wc = warp / 4;
  const int n0 = blockIdx.x * BM, m0 = blockIdx.y * BN, z = blockIdx.z;
  const int nks_all = (K + BK - 1) / BK, per = (nks_all + ksplit - 1) / ksplit;
  const int ks0 = z * per, ks1 = min(nks_all, ks0 + per), nks = ks1 > ks0 ? ks1 - ks0 : 0;
  float acc[1][2][4];
  #pragma unroll
  for (int i = 0; i < 1; i++)
    #pragma unroll
    for (int j = 0; j < 2; j++)
      #pragma unroll
      for (int k = 0; k < 4; k++) acc[i][j][k] = 0.f;
  // weights for stage s (k-step ks0 + s) -> shared buffer buf, 16-byte cp.async, zero-filled past N or K
  // per-thread bases, hoisted out of the k loop: a CTA's stage is RT runs of KTS * 512 contiguous bytes (one per row tile)
  const uint8_t *abase = Wa + ((size_t)(n0 / 16) * nkt + (size_t)ks0 * KTS) * 512;
  const int nblkk = K / SBLK;
  // wload=reg: no shared-memory staging for weights. Each lane loads its own 16 fragment-order bytes per (row tile,
  // k-tile) and its scale words straight from global memory into a register ring that runs PF=2 k-steps ahead of the
  // MMAs, and the format decoder turns them into mma.sync A fragments in place.
  auto issueA = [&](int, int) {};
  (void)abase;
  const int rtw = n0 / 16 + wr * 1;
  uint32_t qr[3][KTS][1][4];
  uint32_t sr[3][1][NBS];  // scale words: row g | row g + 8
  uint32_t sgr[3][KTS][1][5] = {}, tbr[3][KTS][1];  // tbm: lane sign words, tile sign base
  int sgo[3][KTS][1] = {};  // tbm: bit offset of the lane's first sign in sgr[..][0]
#define KG_LOADA(S_, SL_)                                                                                             \
  do {                                                                                                                \
    const int s_ = (S_);                                                                                              \
    _Pragma("unroll") for (int kk = 0; kk < KTS; kk++)                                                                \
      _Pragma("unroll") for (int mm = 0; mm < 1; mm++) {                                                          \
        const int rt = rtw + mm, ktg = (ks0 + s_) * KTS + kk;                                                         \
        kldg128z(qr[SL_][kk][mm], Wa + (((size_t)rt * nkt + ktg) * 32 + lane) * 16, s_ < nks && rt < N / 16 && ktg < nkt); \
        tbr[SL_][kk][mm] = kldg32z(Wt + ((size_t)rt * nkt + ktg) * 4, s_ < nks && rt < N / 16 && ktg < nkt); \
      }                                                                                                               \
    const int blk0 = ((ks0 + s_) * BK) / SBLK;                                                                        \
    _Pragma("unroll") for (int mm = 0; mm < 1; mm++)                                                               \
      _Pragma("unroll") for (int bi = 0; bi < NBS; bi++) {                                                           \
        const int rt = rtw + mm, bl = blk0 + bi;                                                                      \
        const bool okb = s_ < nks && rt < N / 16 && bl < nblkk;                                                       \
        sr[SL_][mm][bi] = kldg32z(Ws + (((size_t)rt * nblkk + bl) * 8 + g) * 4, okb); \
      }                                                                                                               \
  } while (0)
#define KG_LOADS(SL_)                                                                                                 \
  do {                                                                                                                \
    _Pragma("unroll") for (int kk = 0; kk < KTS; kk++)                                                                \
      _Pragma("unroll") for (int mm = 0; mm < 1; mm++) {                                                            \
        const uint32_t *qq = qr[SL_][kk][mm];                                                                         \
        const int cnt = KURN_POPC(qq[0]) + KURN_POPC(qq[1]) + KURN_POPC(qq[2]) + KURN_POPC(qq[3]);                    \
        int x = cnt;                                                                                                  \
        _Pragma("unroll") for (int dd = 1; dd < 32; dd <<= 1) {                                                       \
          const int y = __shfl_sync(KURN_FULL, x, lane >= dd ? lane - dd : lane);                                     \
          if (lane >= dd) x += y;                                                                                     \
        }                                                                                                             \
        const uint32_t bit = tbr[SL_][kk][mm] * 32u + (uint32_t)(x - cnt);                                            \
        sgo[SL_][kk][mm] = (int)(bit & 31u);                                                                          \
        _Pragma("unroll") for (int i = 0; i < 5; i++)                                                                 \
          sgr[SL_][kk][mm][i] = kldg32z(Wg + (bit >> 5) + i, 32 * i < (int)(bit & 31u) + cnt);                        \
      }                                                                                                               \
  } while (0)
  // activations: f16 in slot order (kg_quant), 16-byte cp.async into the swizzled stage buffer
  const uint8_t *X16 = (const uint8_t *)Xin;
  const float *Xsum = (const float *)(X16 + (size_t)M * K * 2);
  (void)Xsum;
  auto issueB = [&](int s, int buf) {
    const int kb = (ks0 + s) * BK;
    for (int e = tid; e < BN * (BK / 8); e += NT) {
      const int col = e / (BK / 8), ch = e % (BK / 8);
      const bool ok = m0 + col < M && kb + ch * 8 < K;
      kcp16(Bs0 + (size_t)buf * B_STAGE + (size_t)col * (BK * 2) + ((ch ^ (col & 7)) * 16),
            ok ? (const void *)(X16 + ((size_t)(m0 + col) * K + kb + ch * 8) * 2) : (const void *)X16, ok ? 16 : 0);
    }
  };  auto compute = [&](int buf, int s) {
    const uint8_t *Ab = As + (size_t)buf * A_STAGE;
    const uint8_t *Sb = Ab + AW_STAGE;
    (void)Sb;
    const int sblk0 = ((ks0 + s) * BK) / SBLK;
    const bool kfull = (ks0 + s + 1) * BK <= K;
    const uint8_t *Bb = Bs0 + (size_t)buf * B_STAGE;
    const float *XS = XS0 + (size_t)buf * (XS_STAGE / 4);
    (void)XS;
    #pragma unroll
    for (int kk = 0; kk < KTS; kk++) {
      uint32_t qa[1][4]; uint32_t sq[1][5]; int sqo[1];
      #pragma unroll
      for (int mm = 0; mm < 1; mm++) { for (int i = 0; i < 4; i++) qa[mm][i] = qr[0][kk][mm][i]; for (int i = 0; i < 5; i++) sq[mm][i] = sgr[0][kk][mm][i]; sqo[mm] = sgo[0][kk][mm]; }
      #pragma unroll
      for (int wl = 0; wl < KT / 32; wl++) {
        const int wlin = kk * (KT / 32) + wl;
        const int kwin = (ks0 + s) * BK + wlin * 32;
        if (!kfull && kwin >= K) continue;
        // dequantize every row tile's A fragments (rows past N have zero scales), then stream B one n8 tile at a time
        uint32_t am[1][2][4];
        float dw0[1], dw1[1];
        #pragma unroll
        for (int mm = 0; mm < 1; mm++) {
        const uint32_t sw = sr[0][mm][(BK >= SBLK ? (wlin * 32) / SBLK : 0)];
        dw0[mm] = kh2f_lo(sw); dw1[mm] = kh2f_hi(sw);
          const uint32_t *q = qa[mm];
          uint32_t (&a)[2][4] = am[mm];
          const uint32_t m16 = (q[wl >> 1] >> (16 * (wl & 1))) & 0xFFFFu;
          int pre = 0;
          #pragma unroll
          for (int w2 = 0; w2 < (wl >> 1); w2++) pre += KURN_POPC(q[w2]);
          if (wl & 1) pre += KURN_POPC(q[wl >> 1] & 0xFFFFu);
          const int pos = sqo[mm] + pre, wi = pos >> 5;
          const uint32_t lo = wi == 0 ? sq[mm][0] : wi == 1 ? sq[mm][1] : wi == 2 ? sq[mm][2] : wi == 3 ? sq[mm][3] : sq[mm][4];
          const uint32_t hi = wi == 0 ? sq[mm][1] : wi == 1 ? sq[mm][2] : wi == 2 ? sq[mm][3] : wi == 3 ? sq[mm][4] : 0u;
          uint32_t sg = kfsr(lo, hi, pos & 31);
          #pragma unroll
          for (int nb = 0; nb < 4; nb++) {
            const uint32_t mn = (m16 >> (4 * nb)) & 15u;
            const uint2 e = tbmlut[(mn << 4) | (sg & 15u)];
            sg >>= KURN_POPC(mn);
            a[nb & 1][nb >> 1] = e.x; a[nb & 1][2 + (nb >> 1)] = e.y;
          }
        }
        #pragma unroll
        for (int nn = 0; nn < 2; nn++) {
          uint32_t b[4];
          const int row = wc * 16 + nn * 8 + (lane & 7);
          kldsm4(b, Bb + (size_t)row * (BK * 2) + (((4 * wlin + (lane >> 3)) ^ (row & 7)) * 16));
          #pragma unroll
          for (int mm = 0; mm < 1; mm++) {
            float d[4];
            const float zz[4] = {0.f, 0.f, 0.f, 0.f};
            kmma16816(d, am[mm][0], b[0], b[1], zz);
            kmma16816(d, am[mm][1], b[2], b[3], d);
            acc[mm][nn][0] += dw0[mm] * d[0];
            acc[mm][nn][1] += dw0[mm] * d[1];
            acc[mm][nn][2] += dw1[mm] * d[2];
            acc[mm][nn][3] += dw1[mm] * d[3];
          }
        }
      }
    }
  };
  KG_LOADA(0, 0);
  KG_LOADA(1, 1);
  KG_LOADS(0);
  #pragma unroll
  for (int s = 0; s < STAGES - 1; s++) {
    if (s < nks) { issueA(s, s); issueB(s, s); }
    kcp_commit();
  }
  for (int ks = 0; ks < nks; ks++) {
    KG_LOADA(ks + 2, 2);
    KG_LOADS(1);
    KCP_WAIT(STAGES - 2);
    __syncthreads();
    const int nx = ks + STAGES - 1;
    if (nx < nks) { issueA(nx, nx % STAGES); issueB(nx, nx % STAGES); }
    kcp_commit();
    compute(ks % STAGES, ks);
    #pragma unroll
    for (int p = 0; p < 2; p++) {
      #pragma unroll
      for (int kk = 0; kk < KTS; kk++)
        #pragma unroll
        for (int mm = 0; mm < 1; mm++)
          #pragma unroll
          for (int i = 0; i < 4; i++) qr[p][kk][mm][i] = qr[p + 1][kk][mm][i];
      #pragma unroll
      for (int mm = 0; mm < 1; mm++)
        #pragma unroll
        for (int bi = 0; bi < NBS; bi++) sr[p][mm][bi] = sr[p + 1][mm][bi];
      #pragma unroll
      for (int kk = 0; kk < KTS; kk++)
        #pragma unroll
        for (int mm = 0; mm < 1; mm++) {
          for (int i = 0; i < 5; i++) sgr[p][kk][mm][i] = sgr[p + 1][kk][mm][i];
          sgo[p][kk][mm] = sgo[p + 1][kk][mm]; tbr[p][kk][mm] = tbr[p + 1][kk][mm];
        }
    }
  }
  KCP_WAIT(0);
#undef KG_LOADA
#undef KG_LOADS  // epilogue: Y[m * N + n]; split z adds its tile after split z-1 (deterministic serial fixup)
  int *flag = &kg_flags[(blockIdx.y * gridDim.x + blockIdx.x) % 262144];
  if (z > 0) {
    if (tid == 0) while (atomicAdd(flag, 0) != z) { }
    __syncthreads();
  }
  #pragma unroll
  for (int mm = 0; mm < 1; mm++)
    #pragma unroll
    for (int nn = 0; nn < 2; nn++)
      #pragma unroll
      for (int e = 0; e < 4; e++) {
        const int row = n0 + (wr * 1 + mm) * 16 + g + 8 * (e >> 1), col = m0 + wc * 16 + nn * 8 + 2 * t + (e & 1);
        if (row < N && col < M) {
          float *y = Y + (size_t)col * N + row;
          *y = z > 0 ? kldcg(y) + acc[mm][nn][e] : acc[mm][nn][e];
        }
      }
  if (ksplit > 1) {
    __threadfence();
    __syncthreads();
    if (tid == 0) atomicExch(flag, z + 1 == ksplit ? 0 : z + 1);
  }
  {  // fused Freivalds check: per block b of FVB output rows, column slot m % FV_MC and probe p, compare
     // sum_n r_p[n] Y[m][n] (this CTA's accumulators) with sum_k F_b[k][p] x[m][k] (fingerprint from kg_fv_setup)
    const uint32_t *fvh = (const uint32_t *)FV;
    const int fb = n0 / FVB, nsw = (N + 31) / 32;
    double *fva = (double *)(FV + FV_ACC(N)) + (size_t)fb * FV_MC * 4;
    double *fvs = (double *)(FV + FV_S2(N)) + (size_t)fb * FV_MC;
    const uint32_t *fsg = (const uint32_t *)(FV + FV_SG(N, K));
    const uint32_t key = fvh[2];
    uint32_t rs = 0u, rv = 0u;  // this lane's rows: probe signs (bit 2 * (2 mm + h) + p) and in-range bits (2 mm + h)
    #pragma unroll
    for (int mm = 0; mm < 1; mm++)
      #pragma unroll
      for (int h = 0; h < 2; h++) {
        const int row = n0 + (wr * 1 + mm) * 16 + g + 8 * h, rb = 2 * mm + h;
        if (row < N) {
          rv |= 1u << rb;
          rs |= ((fsg[row / 32] >> (row % 32)) & 1u) << (2 * rb);
          rs |= ((fsg[nsw + row / 32] >> (row % 32)) & 1u) << (2 * rb + 1);
        }
      }
    #pragma unroll
    for (int nn = 0; nn < 2; nn++)
      #pragma unroll
      for (int ec = 0; ec < 2; ec++) {  // C side: column col, summed over this lane's rows, then over the 8 lanes sharing t
        const int col = m0 + wc * 16 + nn * 8 + 2 * t + ec;
        float c0 = 0.f, c1 = 0.f;
        #pragma unroll
        for (int mm = 0; mm < 1; mm++)
          #pragma unroll
          for (int h = 0; h < 2; h++) {
            const int rb = 2 * mm + h;
            const float v = ((rv >> rb) & 1u) ? acc[mm][nn][2 * h + ec] : 0.f;  // select: rows past N may hold NaN
            c0 += ((rs >> (2 * rb)) & 1u) ? -v : v;
            c1 += ((rs >> (2 * rb + 1)) & 1u) ? -v : v;
          }
        if (col >= M) c0 = c1 = 0.f;  // columns past M were never staged
        #pragma unroll
        for (int o = 4; o < 32; o <<= 1) {
          c0 += __shfl_xor_sync(KURN_FULL, c0, o);
          c1 += __shfl_xor_sync(KURN_FULL, c1, o);
        }
        if (g == 0 && col < M) {
          const uint32_t cs = kfv_csign(key, col);
          double *a = fva + (col % FV_MC) * 4;
          atomicAdd(a, (double)((cs & 1u) ? -c0 : c0));
          atomicAdd(a + 2, (double)((cs & 2u) ? -c1 : c1));
        }
      }
    {  // X side: CTA j of the block's nct takes every nct-th 32-value window of this split, for its BN columns
      const int cps = FVB / BM, j = (n0 % FVB) / BM, nct = min(cps, (N + BM - 1) / BM - fb * cps);
      const int w0 = ks0 * (BK / 32), w1 = min(ks1 * BK, K) / 32;
      const float *Ff = (const float *)(FV + FV_F(N)) + (size_t)fb * K * 2;
      const uint16_t *Fg = (const uint16_t *)(FV + FV_G2(N, K)) + (size_t)fb * K;
      for (int cc = tid % 16; cc < BN; cc += 16) {
        const int m = m0 + cc;
        float x0 = 0.f, x1 = 0.f, s2 = 0.f;
        if (m < M) {
          for (int wi = j + nct * (tid / 16); w0 + wi < w1; wi += nct * 8) {
            const int k0 = (w0 + wi) * 32;
          const uint8_t *xr = (const uint8_t *)Xin + ((size_t)m * K + k0) * 2;  // slot order (kg_x16)
          #pragma unroll
          for (int i = 0; i < 4; i++) {
            const uint4 hv = kld_v4(xr + 16 * i);
            const uint32_t hw[4] = {hv.x, hv.y, hv.z, hv.w};
            #pragma unroll
            for (int q = 0; q < 8; q++) {
              const int s = 8 * i + q, j = s / 16, sl = s % 16, kn = k0 + 8 * ((sl % 8) / 2) + 4 * j + (sl % 2) + 2 * (sl / 8);
              const float xh = KURN_H2F((hw[q >> 1] >> (16 * (q & 1))) & 0xFFFFu);
              const uint2 fw = kld_v2(Ff + 2 * kn);
              const float g2 = __uint_as_float(kld_u16((const uint8_t *)(Fg + kn)) << 16);
              x0 += __uint_as_float(fw.x) * xh; x1 += __uint_as_float(fw.y) * xh; s2 += g2 * xh * xh;
            }
          }
          }
        }
          x0 += __shfl_xor_sync(KURN_FULL, x0, 16); x1 += __shfl_xor_sync(KURN_FULL, x1, 16); s2 += __shfl_xor_sync(KURN_FULL, s2, 16);
        if (lane < 16 && m < M) {
          const uint32_t cs = kfv_csign(key, m);
          double *a = fva + (m % FV_MC) * 4;
          atomicAdd(a + 1, (double)((cs & 1u) ? -x0 : x0));
          atomicAdd(a + 3, (double)((cs & 2u) ? -x1 : x1));
          atomicAdd(fvs + m % FV_MC, (double)s2);
        }
      }
      __shared__ int fvlast;
      __threadfence();
      __syncthreads();
      if (tid == 0) fvlast = atomicAdd((int *)(FV + 64) + fb, 1) == nct * (int)gridDim.y * (int)gridDim.z - 1;
      __syncthreads();
      if (fvlast) {  // every contribution to this block is in: compare (statistical threshold) and reset for the next call
        __threadfence();
        const double tau = (double)__uint_as_float(fvh[3]) * (double)K * 5.9604644775390625e-8;  // lambda K u
        const int ns = min(M, FV_MC);
        for (int sl = tid; sl < FV_MC; sl += NT) {
          volatile double *a = fva + sl * 4, *s = fvs + sl;
          if (sl < ns) {
            const double tb = tau * sqrt(*s) + 1e-30;
            const double q = fmax(fabs(a[0] - a[1]), fabs(a[2] - a[3])) / tb;
            if (!(q <= 1.0)) atomicAdd((int *)FV + 5, 1);  // NaN fails
            else atomicMax((int *)FV + 6, (int)__float_as_uint((float)q));  // worst passing ratio: the false-alarm margin
          }
          a[0] = 0.0; a[1] = 0.0; a[2] = 0.0; a[3] = 0.0; *s = 0.0;
        }
        if (tid == 0) {
          atomicAdd((int *)FV + 4, ns);
          atomicExch((int *)(FV + 64) + fb, 0);
        }
      }
    }
  }
}
#define KG_SRT(rt) (rt)

// KTBM v1 (16-row x 256-value variable-length records, kurn.gpu.tbm) -> the GPU planes, at load, on the device:
//   A      [N/16][K/256][32 lanes][16 B]  presence bits in fragment order: word w, half h = window 2w+h, nibble
//                                         nb = j + 2*rowsel holds values 8t+4j+p (p = 0..3) of row g + 8*rowsel
//   scales [N/16][K/256][8][u32]          d(row g) | d(row g+8) << 16 (TQ2_0's d)
//   toff   [(N/16)*(K/256) + 1] u32       word offset of each tile's sign stream (tile = row tile * K/256 + k-tile)
//   signs  u32 words                      per tile: lane 0's signs, lane 1's, ... bit-continuous (windows, nibbles, p
//                                         ascending; 1 = +1), each tile padded to a word; + slack for 5-word reads
//   roff   [(N/16)*(K/256)] u32           scratch: record offsets relative to v1's data start
// The input must be a v1 buffer for exactly these N (multiple of 16) and K (multiple of 256).
KURN_FN uint64_t ktbm_u64(const uint8_t *p) {  // records sit at arbitrary byte offsets
  uint64_t v = 0;
  for (int i = 0; i < 8; i++) v |= (uint64_t)p[i] << (8 * i);
  return v;
}
KURN_FN int ktbm_pc64(uint64_t v) { return KURN_POPC((uint32_t)v) + KURN_POPC((uint32_t)(v >> 32)); }
#define KTBM_PLANES                                                                                                   \
  const long nt = (long)(N / 16) * (K / 256);                                                                         \
  uint32_t *toff = (uint32_t *)(P + (size_t)nt * 544);                                                                \
  uint32_t *sgn = toff + nt + 1;                                                                                      \
  uint32_t *roff = sgn + (size_t)nt * 128 + 8;                                                                        \
  const size_t data = 64 + (8 * (size_t)(N / 16 + 1) + 63) / 64 * 64;                                                 \
  (void)roff; (void)sgn; (void)data
// pass 1, one thread per 16-row group: walk its records (sizes depend on their nonzero counts)
static __global__ void kg_tbm_walk(const uint8_t *__restrict__ W, uint8_t *__restrict__ P, int N, int K) {
  KTBM_PLANES;
  const int gi = blockIdx.x * blockDim.x + threadIdx.x, nrec = K / 256;
  if (gi >= N / 16) return;
  size_t off = (size_t)ktbm_u64(W + 64 + 8 * (size_t)gi);
  int prt = gi;  // packed row tile of source group gi (the inverse of KG_SRT)
  if (KG_SRT(1) != 1) prt = gi < N / 32 ? 2 * gi : 2 * (gi - N / 32) + 1;
  for (int p = 0; p < nrec; p++) {
    const uint8_t *r = W + data + off;
    int nnz = 0;
    for (int i = 0; i < 64; i++) nnz += ktbm_pc64(ktbm_u64(r + 32 + 8 * i));
    roff[(long)prt * nrec + p] = (uint32_t)off;
    toff[(long)prt * nrec + p] = (uint32_t)((nnz + 31) / 32);
    off += 545 + (size_t)(nnz + 7) / 8;
  }
}
// pass 2, one thread: tile sign sizes (words) -> word offsets
static __global__ void kg_tbm_scan(uint8_t *__restrict__ P, int N, int K) {
  KTBM_PLANES;
  if (blockIdx.x || threadIdx.x) return;
  uint32_t acc = 0;
  for (long i = 0; i < nt; i++) {
    const uint32_t w = toff[i];
    toff[i] = acc;
    acc += w;
  }
  toff[nt] = acc;
}
// pass 3, one warp per record: presence in fragment order, scales, the lanes' compacted signs
static __global__ void kg_tbm_repack(const uint8_t *__restrict__ W, uint8_t *__restrict__ P, int N, int K) {
  KTBM_PLANES;
  __shared__ uint64_t kw[4][64];  // the record's bitmap words, per warp of the 128-thread block
  __shared__ int kpre[4][64];     // their sign-stream prefix (exclusive popcount)
  const long tile = ((long)blockIdx.x * blockDim.x + threadIdx.x) >> 5;
  const int lane = threadIdx.x & 31, wp = (threadIdx.x >> 5) & 3, g = lane >> 2, t = lane & 3;
  if (tile >= nt) return;  // whole warps: blockDim is a multiple of 32
  const uint8_t *r = W + data + roff[tile];
  const uint64_t w0 = ktbm_u64(r + 32 + 16 * lane), w1 = ktbm_u64(r + 40 + 16 * lane);
  const int c0 = ktbm_pc64(w0), c1 = ktbm_pc64(w1);
  int x = c0 + c1;
  for (int dd = 1; dd < 32; dd <<= 1) {
    const int y = __shfl_sync(KURN_FULL, x, lane >= dd ? lane - dd : lane);
    if (lane >= dd) x += y;
  }
  kw[wp][2 * lane] = w0, kw[wp][2 * lane + 1] = w1;
  kpre[wp][2 * lane] = x - c0 - c1, kpre[wp][2 * lane + 1] = x - c1;
  __syncwarp();
  const uint8_t *sb = r + 545;
  uint32_t pres[4] = {0u, 0u, 0u, 0u}, bits[4] = {0u, 0u, 0u, 0u};  // registers: every index below is static or selected
  int nb = 0;
#pragma unroll
  for (int wl = 0; wl < 8; wl++)
#pragma unroll
    for (int q = 0; q < 4; q++) {
      const int j = q & 1, row = g + 8 * (q >> 1), i = 8 * wl + 2 * t + j;  // word of values 32wl + 8t + 4j + (0..3)
      const uint64_t wd = kw[wp][i];
#pragma unroll
      for (int p = 0; p < 4; p++) {
        const int b = 4 * row + p;
        if (!((wd >> b) & 1u)) continue;
        const int si = kpre[wp][i] + ktbm_pc64(wd & ((1ull << b) - 1ull));
        pres[wl >> 1] |= 1u << (16 * (wl & 1) + 4 * q + p);
        const uint32_t m = (uint32_t)((sb[si >> 3] >> (si & 7)) & 1u) << (nb & 31), wi = (uint32_t)nb >> 5;
        bits[0] |= wi == 0 ? m : 0u, bits[1] |= wi == 1 ? m : 0u, bits[2] |= wi == 2 ? m : 0u, bits[3] |= wi == 3 ? m : 0u;
        nb++;
      }
    }
  uint8_t *a = P + ((size_t)tile * 32 + lane) * 16;
  for (int k = 0; k < 4; k++) kst_u32(a + 4 * k, pres[k]);
  if (lane < 8) {
    const uint32_t lo = r[2 * lane] | (r[2 * lane + 1] << 8), hi = r[2 * lane + 16] | (r[2 * lane + 17] << 8);
    kst_u32(P + (size_t)nt * 512 + ((size_t)tile * 8 + lane) * 4, lo | (hi << 16));
  }
  int xs = nb;  // the lanes' exclusive scan of their sign counts: where each lane's bits start in the tile's stream
  for (int dd = 1; dd < 32; dd <<= 1) {
    const int y = __shfl_sync(KURN_FULL, xs, lane >= dd ? lane - dd : lane);
    if (lane >= dd) xs += y;
  }
  const uint32_t w0g = toff[tile], nw = toff[tile + 1] - w0g;
  for (uint32_t k = lane; k < nw; k += 32) sgn[w0g + k] = 0u;
  __syncwarp();
  const uint32_t bit = (uint32_t)(xs - nb), sh = bit & 31u;
  uint32_t *dst = sgn + w0g + (bit >> 5);
#pragma unroll
  for (int k = 0; k < 4; k++) {
    if (32 * k >= nb) break;
    atomicOr(dst + k, bits[k] << sh);
    if (sh) atomicOr(dst + k + 1, bits[k] >> (32u - sh));
  }
}

// f32 X [M][K] -> f16 X16 [M][K] in slot order (one thread per 32-value window)
static __global__ void kg_x16(const float *__restrict__ X, uint8_t *__restrict__ Q, int K, int M) {
  const long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= (long)M * (K / 32)) return;
  const int m = (int)(i / (K / 32)), wdw = (int)(i % (K / 32));
  const float *x = X + (size_t)m * K + (size_t)wdw * 32;
  float xv[32];
  for (int j = 0; j < 32; j++) xv[j] = x[j];
  uint32_t h[16] = {kcvt_h2(xv[1], xv[0]), kcvt_h2(xv[9], xv[8]), kcvt_h2(xv[17], xv[16]), kcvt_h2(xv[25], xv[24]), kcvt_h2(xv[3], xv[2]), kcvt_h2(xv[11], xv[10]), kcvt_h2(xv[19], xv[18]), kcvt_h2(xv[27], xv[26]), kcvt_h2(xv[5], xv[4]), kcvt_h2(xv[13], xv[12]), kcvt_h2(xv[21], xv[20]), kcvt_h2(xv[29], xv[28]), kcvt_h2(xv[7], xv[6]), kcvt_h2(xv[15], xv[14]), kcvt_h2(xv[23], xv[22]), kcvt_h2(xv[31], xv[30])};
  uint8_t *dst = Q + ((size_t)m * K + (size_t)wdw * 32) * 2;
  for (int j = 0; j < 4; j++) ksts128(dst + 16 * j, h[4 * j], h[4 * j + 1], h[4 * j + 2], h[4 * j + 3]);
}
#define KG_FV_OFF(N, K) ((((size_t)(N / 16) * (K / 256) * 544 + ((size_t)(N / 16) * (K / 256) + 1) * 4 + (size_t)(N / 16) * (K / 256) * 512 + 32 + (size_t)(N / 16) * (K / 256) * 4) + 255) / 256 * 256)

// kg_fv_setup: fingerprint, probes and parameters into the region; accumulators and counters zeroed
static __global__ void kg_fv_init(uint8_t *__restrict__ FV, const float *__restrict__ F, const uint16_t *__restrict__ G2,
                                  const uint32_t *__restrict__ sg, int N, int K, uint32_t key, uint32_t lam) {
  const long i = (long)blockIdx.x * blockDim.x + threadIdx.x, nb = FV_NB(N);
  if (i < nb * K * 2) ((float *)(FV + FV_F(N)))[i] = F[i];
  if (i < nb * K) ((uint16_t *)(FV + FV_G2(N, K)))[i] = G2[i];
  if (i < 2L * ((N + 31) / 32)) ((uint32_t *)(FV + FV_SG(N, K)))[i] = sg[i];
  if (i < (long)((FV_F(N) - FV_ACC(N)) / 8)) ((double *)(FV + FV_ACC(N)))[i] = 0.0;
  if (i < nb) ((int *)(FV + 64))[i] = 0;
  if (i < 16) {
    const uint32_t h[9] = {0x3156464Bu, (uint32_t)FVB, key, lam, 0u, 0u, 0u, (uint32_t)N, (uint32_t)K};
    ((uint32_t *)FV)[i] = i < 9 ? h[i] : 0u;
  }
}

// split-K so the grid covers the GPU about twice (each split gets >= 2 k-steps), at most 16
static int kg_auto_split(int N, int K, int M) {
  const long tiles = (long)((N + BM - 1) / BM) * ((M + BN - 1) / BN);
  const int nks = (K + BK - 1) / BK;
  long sk = (2L * kurn_sms() + tiles - 1) / tiles;
  if (sk > nks / 2) sk = nks / 2;
  if (sk > 16) sk = 16;
  return sk < 1 ? 1 : (int)sk;
}

extern "C" {
const char *kg_config(void) { return "op=gemm weights=tbm arch=sm_80 bm=64 bn=16 wm=4 wn=1 bk=256 stages=4 splitk=0 xin=f16 minb=1 wload=reg pf=2 epi=fv fvb=64"; }
int kg_act(void) { return 2; }  // 1: kg_run reads f32 X directly; 2: kg_quant converts X to f16 first
int kg_check_shape(int N, int K, int M) { return (N > 0 && M > 0 && N % 16 == 0 && K > 0 && K % 256 == 0) ? 0 : -1; }
size_t kg_prep_bytes(int N, int K) { return (KG_FV_OFF(N, K) + FV_BYTES(N, K)); }
size_t kg_xbytes(int K, int M) { (void)K; (void)M; return (size_t)M * K * 2; }
int kg_prepare(const void *W, void *Wp, int N, int K, cudaStream_t s) {
  const long ng = N / 16, ntl = ng * (K / 256);
  KURN_LAUNCH(kg_tbm_walk, dim3((unsigned)((ng + 127) / 128)), dim3(128), s, (const uint8_t *)W, (uint8_t *)Wp, N, K);
  KURN_LAUNCH(kg_tbm_scan, dim3(1), dim3(32), s, (uint8_t *)Wp, N, K);
  KURN_LAUNCH(kg_tbm_repack, dim3((unsigned)((ntl * 32 + 127) / 128)), dim3(128), s, (const uint8_t *)W, (uint8_t *)Wp, N, K);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
int kg_quant(const float *X, void *Xq, int K, int M, cudaStream_t s) {
  KURN_LAUNCH(kg_x16, dim3((unsigned)(((long)M * (K / 32) + 127) / 128)), dim3(128), s, X, (uint8_t *)Xq, K, M);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
size_t kg_xblock_bytes(int K, int M) { (void)K; (void)M; return 0; }
int kg_xblocks(const float *X, void *Xb, int K, int M, cudaStream_t s) { (void)X; (void)Xb; (void)K; (void)M; (void)s; return 0; }
int kg_run(const void *W, const void *Xq, float *Y, int N, int K, int M, cudaStream_t s) {
  if (kg_check_shape(N, K, M)) return -1;
  const int sk = kg_auto_split(N, K, M);
#ifndef KURN_EMU
  static int attr = 0;
  if (!attr) { cudaFuncSetAttribute(kg_gemm, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES); attr = 1; }
#endif
  KURN_LAUNCH_SMEM(kg_gemm, dim3((unsigned)((N + BM - 1) / BM), (unsigned)((M + BN - 1) / BN), (unsigned)sk), dim3(128), SMEM_BYTES, s,
                   (const uint8_t *)W, Xq, Y, N, K, M, sk, (uint8_t *)W + KG_FV_OFF(N, K));
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
int kg_epi(void) { return 2; }
int kg_fv_block(void) { return FVB; }
int kg_fv_setup(void *Wp, int N, int K, const float *F, const uint16_t *G2, const uint32_t *signs, uint32_t key, float lambda,
                cudaStream_t s) {
  if (kg_check_shape(N, K, 1)) return -1;
  const long nb = FV_NB(N), nacc = (long)((FV_F(N) - FV_ACC(N)) / 8), nsg = 2L * ((N + 31) / 32);
  long n = nb * K * 2;
  if (nacc > n) n = nacc;
  if (nsg > n) n = nsg;
  uint32_t lam;
  memcpy(&lam, &lambda, 4);
  KURN_LAUNCH(kg_fv_init, dim3((unsigned)((n + 255) / 256)), dim3(256), s, (uint8_t *)Wp + KG_FV_OFF(N, K), F, G2, signs, N, K,
              key, lam);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
int kg_fv_status(const void *Wp, int N, int K, unsigned st[3], cudaStream_t s) {
  const uint8_t *h = (const uint8_t *)Wp + KG_FV_OFF(N, K) + 16;
#ifdef KURN_EMU
  (void)s;
  memcpy(st, h, 12);
  return 0;
#else
  if (cudaMemcpyAsync(st, h, 12, cudaMemcpyDeviceToHost, s) != cudaSuccess) return -1;
  return (int)cudaStreamSynchronize(s);
#endif
}
}
